const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin, terminal: false });

let lines = [];
rl.on('line', (line) => {
    lines.push(line.trim());
});

rl.on('close', () => {
    const b = parseInt(lines[0]);
    let output = "";
    for (let i = 1; i < b; i++) {
        let row = "";
        for (let j = 1; j < b; j++) {
            row += tran(i * j, b) + " ";
        }
        output += row + "\n";
    }
    console.log(output);
});

function tran(a, b) {
    let t;
    let res = 0;
    let pow = 1;
    do {
        t = Math.floor(a / b);
        res += pow * (a - Math.floor(a / b) * b);
        a = t;
        pow *= 10;
    } while (t >= b);
    res += pow * t;
    return res;
}
